const state={page:(location.hash||'#welcome').slice(1),drawer:false,role:'owner',name:'Atanga',business:"Atanga’s Shop",businessType:'Retail',store:'Main Store',currency:'GHS',step:1,selectedCategory:'Retail',mode:'sample',tab:'All',search:'',payment:'Cash',cart:{},modal:null,toast:'',grid:true,settings:{refunds:false,offline:true,receipts:true},data:clone(seed),lastReceipt:null,filterStore:'Main Store',authUser:'',employeeCode:'TB-H9YPCG',isPublicDrawer:false};
